"use strict";(globalThis.webpackChunkogd_handbuch=globalThis.webpackChunkogd_handbuch||[]).push([[255],{3451(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/ogd-handbook/","label":"1. Einstieg","docId":"startseite","unlisted":false},{"type":"category","label":"2. OGD Grundlagen","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/ogd-handbook/ogd_grundlagen/was-ist-ogd","label":"Was ist OGD?","docId":"ogd_grundlagen/was-ist-ogd","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/prinzipien","label":"Zentrale Prinzipien","docId":"ogd_grundlagen/prinzipien","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/fair-care","label":"Leitmotiv FAIR & CARE","docId":"ogd_grundlagen/fair-care","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/ogd-landschaft","label":"OGD-Landschaft Schweiz","docId":"ogd_grundlagen/ogd-landschaft","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_grundlagen/ogd-nutzen","label":"OGD Nutzen","docId":"ogd_grundlagen/ogd-nutzen","unlisted":false}]},{"type":"category","label":"3. OGD im Kanton Z\xfcrich","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/ogd-handbook/ogd_kanton_zh/zugang","label":"Informations- und Datenzugang","docId":"ogd_kanton_zh/zugang","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_kanton_zh/data-governance","label":"Data Governance","docId":"ogd_kanton_zh/data-governance","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_kanton_zh/rechtliche-grundlagen","label":"Rechtliche Grundlagen","docId":"ogd_kanton_zh/rechtliche-grundlagen","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_kanton_zh/datenschutz","label":"Datenschutz","docId":"ogd_kanton_zh/datenschutz","unlisted":false},{"type":"link","href":"/ogd-handbook/ogd_kanton_zh/daten-publizieren","label":"Offene Daten publizieren","docId":"ogd_kanton_zh/daten-publizieren","unlisted":false}]},{"type":"category","label":"4. Daten: Struktur & Format","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/ogd-handbook/daten_struktur_format/dateiformate","label":"Dateiformate","docId":"daten_struktur_format/dateiformate","unlisted":false},{"type":"link","href":"/ogd-handbook/daten_struktur_format/datenstruktur","label":"Datenstruktur","docId":"daten_struktur_format/datenstruktur","unlisted":false},{"type":"link","href":"/ogd-handbook/daten_struktur_format/spalten\xfcberschriften","label":"Spalten\xfcberschriften","docId":"daten_struktur_format/spalten\xfcberschriften","unlisted":false},{"type":"link","href":"/ogd-handbook/daten_struktur_format/datentypen","label":"Datentypen","docId":"daten_struktur_format/datentypen","unlisted":false},{"type":"link","href":"/ogd-handbook/daten_struktur_format/geografische-referenzierung","label":"Geografische Referenzierung","docId":"daten_struktur_format/geografische-referenzierung","unlisted":false},{"type":"link","href":"/ogd-handbook/daten_struktur_format/fehlende-werte","label":"Fehlende Werte","docId":"daten_struktur_format/fehlende-werte","unlisted":false},{"type":"link","href":"/ogd-handbook/daten_struktur_format/aktualisierungsstrategie","label":"Aktualisierungsstrategie","docId":"daten_struktur_format/aktualisierungsstrategie","unlisted":false}]},{"type":"link","href":"/ogd-handbook/metadaten","label":"5. Metadaten","docId":"metadaten","unlisted":false},{"type":"category","label":"6. Anleitungen","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/ogd-handbook/anleitungen/r-skript-beispiel","label":"R-Skript Beispiel","docId":"anleitungen/r-skript-beispiel","unlisted":false},{"type":"link","href":"/ogd-handbook/anleitungen/muster-ogd","label":"Muster OGD","docId":"anleitungen/muster-ogd","unlisted":false},{"type":"link","href":"/ogd-handbook/anleitungen/excel-zu-csv","label":"Excel zu CSV konvertieren","docId":"anleitungen/excel-zu-csv","unlisted":false},{"type":"link","href":"/ogd-handbook/anleitungen/anleitungen-metadatenverwaltung","label":"Anleitungen Metadatenverwaltung","docId":"anleitungen/anleitungen-metadatenverwaltung","unlisted":false}]},{"type":"link","href":"/ogd-handbook/kontakt","label":"7. Kontakt","docId":"kontakt","unlisted":false}]},"docs":{"anleitungen/anleitungen-metadatenverwaltung":{"id":"anleitungen/anleitungen-metadatenverwaltung","title":"Anleitungen Metadatenverwaltung","description":"Metadaten und Daten werden im kantonalen Tool Metadatenverwaltung verwaltet. Die Logindetails erhaltet ihr bei der Data Steward Einf\xfchrung.","sidebar":"tutorialSidebar"},"anleitungen/excel-zu-csv":{"id":"anleitungen/excel-zu-csv","title":"Excel zu CSV konvertieren","description":"F\xfcr die Publikation als OGD m\xfcssen Excel-Dateien als CSV exportiert werden. Die Anforderungen an das Format sind in den Dateiformatvorgaben beschrieben.","sidebar":"tutorialSidebar"},"anleitungen/muster-ogd":{"id":"anleitungen/muster-ogd","title":"Muster OGD","description":"","sidebar":"tutorialSidebar"},"anleitungen/r-skript-beispiel":{"id":"anleitungen/r-skript-beispiel","title":"Daten nachvollziehbar aufbereiten","description":"Die Daten die du als OGD ver\xf6ffentlichen m\xf6chtest liegen j\xe4hrlich (oder in anderen regelm\xe4ssigen Abst\xe4nden) vor? Du m\xf6chtest selbst nachvollziehen, wie du die Daten das letzte Jahr aufbereitet hast oder deine Datenaufbereitung in Zukunft einfach \xfcbergeben k\xf6nnen?","sidebar":"tutorialSidebar"},"daten_struktur_format/aktualisierungsstrategie":{"id":"daten_struktur_format/aktualisierungsstrategie","title":"Aktualisierungsstrategie von Distributionen","description":"Wenn sich Daten \xfcber die Zeit ver\xe4ndern, k\xf6nnen diese auf unterschiedliche Arten im Datenkatalog aktualisiert werden. Es gibt zwei grundlegende Strategien:","sidebar":"tutorialSidebar"},"daten_struktur_format/dateiformate":{"id":"daten_struktur_format/dateiformate","title":"Dateiformate","description":"Die Verwendung offener, maschinenlesbarer Dateiformate ist eine Pflichtanforderung f\xfcr OGD im Kanton Z\xfcrich. Alle weiteren Empfehlungen in diesem Kapitel verbessern die Qualit\xe4t und Weiterverwendbarkeit der Daten erheblich - sind aber keine harten Anforderungen. ToDo: Erg\xe4nzen was wir nicht akzeptieren.","sidebar":"tutorialSidebar"},"daten_struktur_format/datenstruktur":{"id":"daten_struktur_format/datenstruktur","title":"Datenstruktur","description":"Tidy Data","sidebar":"tutorialSidebar"},"daten_struktur_format/datentypen":{"id":"daten_struktur_format/datentypen","title":"Datentypen","description":"Jede Spalte enth\xe4lt Werte eines einzigen Datentyps. Die folgenden Formatvorgaben stellen sicher, dass Daten maschinell korrekt verarbeitet werden k\xf6nnen. Die Empfehlungen sind wie folgt:","sidebar":"tutorialSidebar"},"daten_struktur_format/fehlende-werte":{"id":"daten_struktur_format/fehlende-werte","title":"Unbekannte und fehlende Werte","description":"Fehlende oder unbekannte Werte sollen einheitlich und klar gekennzeichnet sein, damit sie korrekt interpretiert werden.","sidebar":"tutorialSidebar"},"daten_struktur_format/geografische-referenzierung":{"id":"daten_struktur_format/geografische-referenzierung","title":"Geografische Referenzierung","description":"Viele Verwaltungsdaten haben einen r\xe4umlichen Bezug wie eine Gemeinde oder ein Bezirk. Damit diese Daten mit anderen Datens\xe4tzen verkn\xfcpft werden k\xf6nnen (unabh\xe4ngig von Schreibweisen oder Namens\xe4nderungen) m\xfcssen r\xe4umliche Angaben einheitlich referenziert werden. Die offiziellen Codes und Namen zu Gemeinden, Bezirken und Raumplanungsregionen des Kantons Z\xfcrich sind im Datenkatalog verf\xfcgbar: Gebietsstammdaten | Datenkatalog Kanton Z\xfcrich","sidebar":"tutorialSidebar"},"daten_struktur_format/spalten\xfcberschriften":{"id":"daten_struktur_format/spalten\xfcberschriften","title":"Spalten\xfcberschriften","description":"Die erste Zeile eines Datensatzes enth\xe4lt immer die Spalten\xfcberschriften - danach folgen die Datenzeilen. F\xfcr diese Spalten\xfcberschriften (Variablennamen) gelten folgende Empfehlungen:","sidebar":"tutorialSidebar"},"kontakt":{"id":"kontakt","title":"7. Kontakt","description":"","sidebar":"tutorialSidebar"},"metadaten":{"id":"metadaten","title":"Metadaten","description":"Metadaten beschreiben einen Datensatz und setzen ihn in Kontext. Sie beschreiben, wof\xfcr die Daten erhoben wurden, welche Einschr\xe4nkungen oder Br\xfcche in der Erhebung zu beachten sind, die zeitliche und r\xe4umliche Abdeckung und geben Hinweise auf weitere Hintergrundinformationen.","sidebar":"tutorialSidebar"},"ogd_grundlagen/fair-care":{"id":"ogd_grundlagen/fair-care","title":"Leitmotiv FAIR & CARE","description":"Die Leitmotive \\"FAIR & CARE\\" konkretisieren die Anforderungen an Qualit\xe4t und verantwortungsvollen Umgang mit Open Government Data. Dieses Leitmotiv verbindet technische Offenheit mit verantwortungsvollem Handeln.","sidebar":"tutorialSidebar"},"ogd_grundlagen/ogd-landschaft":{"id":"ogd_grundlagen/ogd-landschaft","title":"OGD-Landschaft Schweiz","description":"Open Government Data werden in der Schweiz auf verschiedenen Ebenen bereitgestellt - von Gemeinden und Kantonen \xfcber den Bund bis hin zur europ\xe4ischen Ebene. Viele Kantone und gr\xf6ssere Gemeinden betreiben eigenst\xe4ndige Datenkataloge mit eigener Datenhaltung. Sie sind der Ursprung vieler Datens\xe4tze und verantwortlich f\xfcr deren Pflege und Qualit\xe4t.","sidebar":"tutorialSidebar"},"ogd_grundlagen/ogd-nutzen":{"id":"ogd_grundlagen/ogd-nutzen","title":"OGD Nutzen","description":"Offene Daten entfalten ihren Nutzen erst, wenn sie auch tats\xe4chlich verwendet werden. Ein aktiver Feedbackloop zwischen Nutzenden und Datenpublizierenden ist dabei zentral: Nur so k\xf6nnen fehlende Datens\xe4tze identifiziert, bestehende verbessert und das Angebot gezielt weiterentwickelt werden.","sidebar":"tutorialSidebar"},"ogd_grundlagen/prinzipien":{"id":"ogd_grundlagen/prinzipien","title":"Zentrale Prinzipien","description":"Damit offene Verwaltungsdaten optimal genutzt werden und Wirkung entfalten k\xf6nnen, m\xfcssen sie bestimmten Grunds\xe4tzen folgen. Diese Grunds\xe4tze sind in der International Open Data Charter festgehalten - einem international anerkannten Rahmenwerk f\xfcr offene Daten.","sidebar":"tutorialSidebar"},"ogd_grundlagen/was-ist-ogd":{"id":"ogd_grundlagen/was-ist-ogd","title":"Was ist OGD?","description":"Dieses Kapitel erkl\xe4rt, was offene Beh\xf6rdendaten (OGD) sind, warum sie wichtig sind und wo sie genutzt werden k\xf6nnen.","sidebar":"tutorialSidebar"},"ogd_kanton_zh/data-governance":{"id":"ogd_kanton_zh/data-governance","title":"Data Governance","description":"Die Organisation, das Rollenmodell, die Standards und Infrastruktur f\xfcr Open Government Data ist Teil der Data Governance der Kantonsverwaltung. Der Kanton Z\xfcrich hat eine f\xf6derierte Data Governance, wir streben keine Zentralisierung an. Stattdessen bieten wir die Beratung, Schulung und Infrastruktur, die \xc4mter und Fachstellen ben\xf6tigen, um ihre Daten gut und sicher zu halten und, im Fall von OGD, zu publizieren. Die Data Governance wird momentan im Regierungsrat beraten. Der Regierungsratsantrag mit allen Infos liegt hier.","sidebar":"tutorialSidebar"},"ogd_kanton_zh/daten-publizieren":{"id":"ogd_kanton_zh/daten-publizieren","title":"Offene Daten publizieren","description":"F\xfcnf Schritte, um Daten offen verf\xfcgbar zu machen","sidebar":"tutorialSidebar"},"ogd_kanton_zh/datenschutz":{"id":"ogd_kanton_zh/datenschutz","title":"Datenschutz","description":"F\xfcr die Publikation von Open Data, wie von Information generell, ist eine Abw\xe4gung n\xf6tig zwischen dem \xf6ffentlichen Interesse an der Bekanntgabe und einem \xf6ffentlichen oder privaten Interesse an der eingeschr\xe4nkten Zug\xe4nglichkeit (\xf6ffentliche Sicherheit, Datenschutz, Privatsph\xe4re). Je h\xf6her das berechtigte \xf6ffentliche Interesse ist, umso gewichtiger muss auch die Verletzung der Privatsph\xe4re oder der \xf6ffentlichen Sicherheit sein.","sidebar":"tutorialSidebar"},"ogd_kanton_zh/rechtliche-grundlagen":{"id":"ogd_kanton_zh/rechtliche-grundlagen","title":"Rechtliche Grundlagen","description":"Die Kantonsverwaltung Z\xfcrich darf, basierend auf dem Informations- und Datenschutzgesetz IDG, open data publizieren. 2017 beschloss der Regierungsrat den Aufbau eines kantonalz\xfcrcherischen OGD-Angebots und best\xe4tigte seither in den Digitalisierungsstrategien stets den Wunsch nach umfassenden Open Data, um eGovernment, Transparenz und Digitalisierung des Kantons zu f\xf6rdern.","sidebar":"tutorialSidebar"},"ogd_kanton_zh/zugang":{"id":"ogd_kanton_zh/zugang","title":"Informations- und Datenzugang","description":"Vom Amtsgeheimnis zur offenen Verwaltung","sidebar":"tutorialSidebar"},"startseite":{"id":"startseite","title":"1. Einstieg","description":"","sidebar":"tutorialSidebar"}}}}')}}]);